INSERT INTO `meeting_stt_summary` VALUES (1,1,NULL,'MIXED','/uploads/meetings/1/stt/mixed/summary.txt','[{\"id\":1,\"content\":\"사과포도: 채팅 서버 구현을 위한 의존성 추가 및 컨피규레이션 클래스 작성\",\"assigneeId\":null,\"status\":\"TODO\"}]',NULL,NULL,'2026-02-02 02:01:57','2026-02-02 02:04:42','REALTIME_STT'),(2,2,NULL,'MIXED','/uploads/meetings/2/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-02 09:45:36','2026-02-02 09:45:36','UNKNOWN'),(3,4,NULL,'MIXED','/uploads/meetings/4/stt/mixed/summary.txt','[{\"id\":2,\"content\":\"도커 명령어를 익혀서 딥러닝 모델 실행 및 코딩 시 활용하기\",\"assigneeId\":null,\"status\":\"TODO\"}]',NULL,NULL,'2026-02-02 11:57:52','2026-02-02 11:57:52','REALTIME_STT'),(4,5,NULL,'MIXED','/uploads/meetings/5/stt/mixed/summary.txt','[{\"id\":3,\"content\":\"성경훈은 스터디 관련 예산 및 정답 처리에 대한 추가 조사 수행\",\"assigneeId\":null,\"status\":\"TODO\"}]',NULL,NULL,'2026-02-02 13:12:51','2026-02-02 13:12:51','REALTIME_STT'),(5,6,NULL,'MIXED','/uploads/meetings/6/stt/mixed/summary.txt','[{\"id\":8,\"content\":\"Git을 설치하고 설정하여 개인 작업 폴더를 준비하기\",\"assigneeId\":null,\"status\":\"TODO\"}]',NULL,NULL,'2026-02-02 14:51:07','2026-02-02 16:15:31','REALTIME_STT'),(6,7,NULL,'MIXED','/uploads/meetings/7/stt/mixed/summary.txt','[{\"id\":7,\"content\":\"팀원들은 각자의 역할에 따라 주요 마일스톤을 설정하고 진행 상황을 주기적으로 공유하기로 하였다.\",\"assigneeId\":null,\"status\":\"TODO\"}]',NULL,NULL,'2026-02-02 16:06:01','2026-02-02 16:06:01','FULL_AUDIO'),(7,2073,NULL,'MIXED','/uploads/meetings/2073/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-02 16:51:47','2026-02-02 16:51:47','REALTIME_STT'),(9,2074,NULL,'MIXED','/uploads/meetings/2074/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-02 22:17:36','2026-02-02 22:17:36','UNKNOWN'),(12,2075,NULL,'MIXED','/uploads/meetings/2075/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-02 22:54:38','2026-02-02 22:54:38','UNKNOWN'),(13,2076,NULL,'MIXED','/uploads/meetings/2076/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-02 23:36:17','2026-02-02 23:36:17','UNKNOWN'),(15,2077,NULL,'MIXED','/uploads/meetings/2077/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-03 10:29:31','2026-02-03 10:29:31','UNKNOWN'),(16,2080,NULL,'MIXED','/uploads/meetings/2080/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-03 13:19:36','2026-02-03 13:19:36','UNKNOWN'),(18,2078,NULL,'MIXED','/uploads/meetings/2078/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-03 13:23:29','2026-02-03 13:23:29','UNKNOWN'),(19,2081,NULL,'MIXED','/uploads/meetings/2081/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-03 13:40:26','2026-02-03 13:40:26','UNKNOWN'),(20,2082,NULL,'MIXED','/uploads/meetings/2082/stt/mixed/summary.txt','[{\"id\":790,\"content\":\"도커 공식 홈페이지에서 Docker Desktop 설치하고 기본 명령어(docker run, pull, build, ps, stop) 실습하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":791,\"content\":\"간단한 웹 애플리케이션을 도커 이미지로 빌드하고 컨테이너로 실행해보기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":792,\"content\":\"Docker Hub에서 공개 이미지 검색하고 다운로드하여 로컬에서 실행해보기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":793,\"content\":\"Dockerfile 작성법을 학습하고 직접 커스텀 이미지 생성해보기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":794,\"content\":\"도커 컨테이너 간 네트워킹과 볼륨 마운트 개념 실습하기\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"도커\",\"컨테이너\",\"가상화\",\"이미지\",\"Dockerfile\",\"Docker Hub\",\"마이크로서비스\",\"DevOps\",\"CI/CD\",\"오케스트레이션\",\"포트포워딩\",\"볼륨마운트\",\"레지스트리\"]','[\"도커는 애플리케이션과 실행 환경을 컨테이너로 패키징하여 환경 독립적인 배포를 가능하게 합니다\",\"기존 가상머신 대비 가볍고 빠른 실행이 가능한 OS 레벨 가상화 기술입니다\",\"개발-테스트-운영 환경 간의 일관성을 보장하여 \'내 컴퓨터에서는 잘 되는데\' 문제를 해결합니다\",\"마이크로서비스 아키텍처와 클라우드 네이티브 개발의 핵심 인프라 기술입니다\"]','2026-02-03 14:53:37','2026-02-03 14:53:47','REALTIME_STT'),(21,2083,NULL,'MIXED','/uploads/meetings/2083/stt/mixed/summary.txt','[{\"id\":795,\"content\":\"각 팀원은 담당 역할에 따른 세부 작업 계획서를 작성하고 다음 회의 전까지 공유\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":796,\"content\":\"프로젝트 마일스톤별 구체적인 달성 목표와 완료 기준을 문서화하여 팀 저장소에 업로드\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":797,\"content\":\"주간 진행 상황 보고서 템플릿을 제작하고 매주 금요일 정기 공유 일정 확정\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":798,\"content\":\"AI 데이터 분석 도구의 MVP(최소 기능 제품) 요구사항 명세서 초안 작성\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":799,\"content\":\"기술 스택 조사 및 개발 환경 설정 방안 연구하여 다음 회의에서 발표\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":800,\"content\":\"프로젝트 관리 도구(예: Jira, Trello) 선정 및 팀 워크스페이스 구축\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"AI\",\"데이터분석\",\"머신러닝\",\"역할분담\",\"마일스톤\",\"MVP\",\"MLOps\"]','[\"AI 기반 데이터 분석 도구의 핵심 기능과 비즈니스 적용 사례를 구체적으로 정의\",\"팀원들의 전문성을 고려한 명확한 역할 분담과 책임 영역 설정 완료\",\"프로젝트 성공을 위한 단계별 마일스톤과 완료 기준 합의\",\"정기적인 진행 상황 공유와 효율적인 팀 소통 체계 구축\",\"개발부터 배포까지의 전체 프로젝트 로드맵 수립\"]','2026-02-03 16:56:38','2026-02-03 16:56:38','FULL_AUDIO'),(22,2087,NULL,'MIXED','/uploads/meetings/2087/stt/mixed/summary.txt','[{\"id\":801,\"content\":\"테스트 케이스 작성 템플릿 준비 및 테스트 시나리오 설계\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":802,\"content\":\"3시간 테스트 미팅을 위한 협업 환경(화상회의, 화면공유 등) 셋업\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":803,\"content\":\"버그 탐지 도구 및 방법론 사전 조사 및 준비\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":804,\"content\":\"테스트 대상 소프트웨어 또는 애플리케이션 선정 및 환경 구성\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"테스팅\",\"테스트케이스\",\"버그탐지\",\"품질보증\",\"소프트웨어테스트\",\"협업환경\",\"테스트방법론\",\"미팅\",\"QA\"]','[\"3시간 분량의 테스트 미팅을 통해 체계적인 소프트웨어 테스팅 프로세스를 학습한다\",\"테스트 케이스 작성을 먼저 완료한 후 실제 버그 탐지 작업을 순차적으로 진행한다\",\"협업 환경을 구축하여 팀 전체가 실시간으로 소통하며 테스팅을 수행한다\",\"실무 적용 가능한 버그 발견 기법과 테스트 방법론을 중점적으로 다룬다\"]','2026-02-04 09:21:09','2026-02-04 09:21:48','REALTIME_STT'),(23,2089,NULL,'MIXED','/uploads/meetings/2089/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-04 14:47:09','2026-02-04 14:47:09','UNKNOWN'),(24,2090,NULL,'MIXED','/uploads/meetings/2090/stt/mixed/summary.txt',NULL,NULL,NULL,'2026-02-04 15:17:02','2026-02-04 15:17:02','UNKNOWN'),(25,2093,NULL,'MIXED','/uploads/meetings/2093/stt/mixed/summary.txt','[{\"id\":805,\"content\":\"다음 회의까지 각 팀원의 협업 도구에서 채팅 알림 설정을 개인 업무 패턴에 맞게 조정하고 결과 공유\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":806,\"content\":\"화면 공유 시 발생하는 기술적 문제점들을 문서화하고 대안 솔루션 3가지 이상 조사\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":807,\"content\":\"1,000원 예산 내에서 실현 가능한 프로젝트 범위를 재정의하고 우선순위 매트릭스 작성\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":808,\"content\":\"표준 발표 템플릿과 회의 종료 체크리스트를 작성하여 다음 회의에서 시범 적용\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"화면 공유\",\"채팅\",\"알림 설정\",\"타깃\",\"발표\",\"종료\",\"WebRTC\",\"협업 도구\",\"예산 관리\",\"사용자 경험\",\"MVP\",\"성능 최적화\"]','[\"화면 공유 기능의 안정성 문제와 이를 해결하기 위한 기술적 접근 방안 도출\",\"채팅 알림 설정의 사용자 맞춤형 최적화를 통한 업무 효율성 향상 방안\",\"1,000원대 예산 제약 하에서의 현실적인 프로젝트 타깃 설정 및 우선순위 결정\",\"회의 발표와 종료 프로세스의 표준화를 통한 스터디 운영 체계 개선\"]','2026-02-04 17:06:28','2026-02-04 17:07:08','REALTIME_STT'),(26,2095,NULL,'MIXED','/uploads/meetings/2095/stt/mixed/summary.txt','[{\"id\":809,\"content\":\"각 팀원은 담당 역할에 따라 1주일 내에 세부 작업 계획서를 작성하고 첫 번째 마일스톤 달성 목표일을 설정한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":810,\"content\":\"주간 진행 상황 공유를 위한 정기 미팅 일정(매주 특정 요일)을 확정하고 회의 진행 방식을 정한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":811,\"content\":\"AI 데이터 분석 도구 개발을 위한 기술 스택과 개발 환경을 조사하고 팀 내에서 통일된 개발 표준을 수립한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":812,\"content\":\"프로젝트 문서화 및 버전 관리를 위한 협업 도구(Git, 프로젝트 관리 툴 등)를 선정하고 환경을 구축한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":813,\"content\":\"데이터 분석 요구사항과 목표 성능 지표를 구체적으로 정의하고 문서화한다\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"AI\",\"데이터분석\",\"머신러닝\",\"역할분담\",\"마일스톤\",\"프로젝트관리\",\"협업\"]','[\"AI 기반 데이터 분석 도구의 핵심 기능과 실제 적용 가능한 사용 사례에 대한 구체적 논의가 이루어졌다\",\"팀원들의 전문성을 고려한 명확한 역할 분담과 책임 영역 설정이 완료되었다\",\"프로젝트 진행을 위한 단계별 마일스톤과 각 단계의 목표 및 완료 기준이 합의되었다\",\"효율적인 팀 협업을 위한 정기적 진행 상황 공유 체계 구축 방안이 결정되었다\"]','2026-02-05 10:24:17','2026-02-05 10:24:17','FULL_AUDIO'),(27,2097,NULL,'MIXED','/uploads/meetings/2097/stt/mixed/summary.txt','[{\"id\":814,\"content\":\"A형 발표 자료 작성 및 발표 순서, 시간 배분 계획 수립하여 다음 회의 전까지 공유\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":815,\"content\":\"정보처리기사 필기/실기 학습 계획서 개인별로 작성하여 스터디 그룹에 공유\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":816,\"content\":\"스터디 재원 관련 예산안 및 분담 방식 구체화하여 문서로 정리\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":817,\"content\":\"다음 스터디 세션 주제 및 진행 방식 확정하여 일주일 전 공지\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"정보처리기사\",\"필기시험\",\"실기시험\",\"A형발표\",\"재원계획\",\"학습전략\",\"자격증\",\"IT스터디\",\"팀학습\"]','[\"정보처리기사 필기와 실기 시험의 상대적 중요도와 학습 우선순위에 대한 심층 토론 진행\",\"개인별 자격증 취득 목표와 현재 수준에 따른 맞춤형 학습 전략 수립\",\"A형 발표 준비를 위한 구체적인 계획 수립 및 팀원 간 역할 분담 합의\",\"스터디 재원 및 운영 방식에 대한 효율적인 방안 도출\"]','2026-02-05 10:31:30','2026-02-05 10:31:30','REALTIME_STT'),(28,2096,NULL,'MIXED','/uploads/meetings/2096/stt/mixed/summary.txt','[{\"id\":818,\"content\":\"AI 웹 애플리케이션의 사용자 경험 개선 방안을 구체적인 와이어프레임과 프로토타입을 포함한 상세 문서로 작성하고, 접근성 가이드라인 및 성능 요구사항을 명시하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":819,\"content\":\"코드 리뷰 프로세스의 체크리스트 작성 및 주기적 검토 일정 수립하여, 매주 금요일 코드 리뷰 회의를 통해 개선사항 점검하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":820,\"content\":\"AI 기능 구현을 위한 기술 스택 선정 및 아키텍처 설계안 작성하여, 개발 환경 구축 및 테스트 전략 수립하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":821,\"content\":\"팀 협업 도구 및 커뮤니케이션 채널 최적화를 위한 워크플로우 정의서 작성 및 역할 분담 명확화하기\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"AI 웹 애플리케이션\",\"사용자 경험\",\"코드 리뷰\",\"팀 협업\",\"머신러닝 통합\",\"UX/UI 설계\",\"성능 최적화\"]','[\"AI 기능을 웹 애플리케이션에 자연스럽게 통합하기 위한 UX/UI 설계 원칙과 성능 최적화 방안이 논의되었습니다\",\"사용자 중심의 AI 서비스 설계를 위해 접근성과 직관성을 고려한 인터페이스 개발 방향이 설정되었습니다\",\"팀 내 코드 리뷰 프로세스의 체계화를 통해 코드 품질 향상과 효과적인 지식 공유 방안이 마련되었습니다\",\"AI 웹 애플리케이션 개발 시 고려해야 할 기술적 요구사항과 구현 방법론에 대한 구체적인 가이드라인이 논의되었습니다\"]','2026-02-05 10:32:30','2026-02-05 10:32:30','FULL_AUDIO'),(29,2098,NULL,'MIXED','/uploads/meetings/2098/stt/mixed/summary.txt','[{\"id\":822,\"content\":\"각 팀원은 담당 영역의 상세 개발 계획과 구체적인 마일스톤 일정을 2주 내에 수립하여 팀에 공유한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":823,\"content\":\"주간 진행상황 보고서를 매주 금요일까지 작성하여 팀 전체에 공유하고 이슈사항을 논의한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":824,\"content\":\"AI 모델 설계 담당자는 데이터 분석 요구사항 명세서를 작성하고 기술 스택을 확정한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":825,\"content\":\"UI/UX 담당자는 사용자 인터페이스 목업과 사용성 테스트 계획을 수립한다\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":826,\"content\":\"다음 회의 전까지 각자 담당 기술 영역의 레퍼런스 조사와 벤치마킹 자료를 준비한다\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"AI 기반 데이터 분석\",\"역할 분담\",\"마일스톤 관리\",\"머신러닝 모델\",\"프로젝트 협업\",\"데이터 파이프라인\",\"사용자 경험\"]','[\"AI 기반 데이터 분석 도구의 핵심 기능과 사용 사례를 구체적으로 정의하고 기술 요구사항을 명확히 설정했습니다\",\"각 팀원의 전문 분야를 고려한 역할 분담과 책임 영역을 명확히 하여 효율적인 협업 체계를 구축했습니다\",\"프로젝트 완료까지의 주요 마일스톤과 중간 점검 일정을 설정하여 체계적인 진행 관리 방안을 수립했습니다\",\"정기적인 진행상황 공유와 피드백 체계를 마련하여 프로젝트 품질 관리 방안을 확립했습니다\"]','2026-02-05 15:28:10','2026-02-05 15:28:10','FULL_AUDIO'),(30,2105,NULL,'MIXED','/uploads/meetings/2105/stt/mixed/summary.txt','[{\"id\":827,\"content\":\"150만원 예산 관련 구체적인 항목별 비용 분석 및 견적서 수집 (1주일 내)\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":828,\"content\":\"유사 프로젝트 사례 조사 및 투자 대비 효과 분석 보고서 작성\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":829,\"content\":\"예산 사용 계획서 초안 작성 및 우선순위별 항목 정리\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":830,\"content\":\"대안 방안 검토 및 리스크 분석 자료 준비\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":831,\"content\":\"다음 회의까지 stakeholder 의견 수렴 및 피드백 정리\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"150만원\",\"예산계획\",\"투자분석\",\"ROI\",\"비용효율성\",\"프로젝트관리\",\"IT거버넌스\"]','[\"150만원 예산에 대한 구체적인 투자 계획 논의가 회의의 핵심 안건이었음\",\"해당 금액의 타당성과 효율적 활용 방안에 대한 심층 검토 필요성이 제기됨\",\"투자 대비 효과 분석을 통한 최적화된 예산 사용 계획 수립이 합의됨\",\"추가적인 시장 조사와 기술 분석을 통해 더 정확한 판단 기준 마련이 요구됨\"]','2026-02-05 17:33:25','2026-02-05 17:33:25','FULL_AUDIO'),(31,2107,NULL,'MIXED','/uploads/meetings/2107/stt/mixed/summary.txt','[{\"id\":832,\"content\":\"150만원의 구체적인 사용처(장비구입, 개발비용, 교육비 등)를 관련 담당자에게 확인하고 문서화하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":833,\"content\":\"해당 금액과 관련된 프로젝트명, 승인 여부, 집행 일정을 명확히 정리하여 다음 회의에서 공유하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":834,\"content\":\"회의록 작성 템플릿을 개선하여 예산 관련 논의 시 필수 기록 항목(목적, 금액, 일정, 승인자 등)을 포함하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":835,\"content\":\"회의 진행 시 실시간으로 중요 내용을 확인하고 검증하는 프로세스 도입하기\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":836,\"content\":\"다음 회의까지 예산 관련 모든 미결 사항을 정리하여 참석자들에게 사전 공유하기\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"예산관리\",\"프로젝트관리\",\"회의록\",\"액션아이템\",\"IT거버넌스\",\"비용관리\",\"협업\"]','[\"150만원이라는 구체적인 금액이 회의에서 언급되었으나 사용처가 불분명함\",\"예산 관련 논의의 세부사항이 충분히 기록되지 않아 추가 정보 수집이 필요함\",\"회의록의 완성도가 낮아 참석자들 간의 이해도 차이가 발생할 가능성이 있음\",\"IT 프로젝트 관리에서 예산 투명성의 중요성이 부각됨\",\"향후 회의 진행 시 보다 체계적인 기록 관리가 필요함\"]','2026-02-05 18:35:46','2026-02-05 18:35:46','FULL_AUDIO'),(32,2110,NULL,'MIXED','/uploads/meetings/2110/stt/mixed/summary.txt','[{\"id\":837,\"content\":\"각 팀원은 담당 영역(프론트엔드/백엔드/AI-ML/데이터)별로 상세한 기술 스펙과 구현 계획서를 작성하여 다음 회의 전까지 공유한다.\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":838,\"content\":\"프로젝트 관리자는 전체 마일스톤 일정표를 작성하고 각 단계별 완료 기준과 검증 방법을 문서화한다.\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":839,\"content\":\"AI/ML 담당자는 데이터 분석 도구에 적용할 AI 모델 후보군을 조사하고 성능 비교 분석 자료를 준비한다.\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":840,\"content\":\"팀 전체는 매주 금요일 오후에 진행 상황을 공유하는 정기 회의를 개최하고, 이슈 사항을 즉시 논의한다.\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":841,\"content\":\"데이터 처리 담당자는 분석 대상 데이터의 형태와 전처리 요구사항을 조사하여 데이터 파이프라인 설계안을 작성한다.\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"AI 기반 데이터 분석\",\"머신러닝\",\"역할 분담\",\"마일스톤 관리\",\"데이터 파이프라인\",\"프로젝트 협업\",\"실시간 분석\"]','[\"AI 기반 데이터 분석 도구의 핵심 기능과 실제 비즈니스 활용 사례를 구체적으로 정의했습니다.\",\"팀원들의 전문 분야를 고려하여 프론트엔드, 백엔드, AI/ML, 데이터 처리 등 역할을 체계적으로 분담했습니다.\",\"프로젝트 완료까지의 주요 마일스톤과 각 단계별 목표 및 완료 기준을 설정했습니다.\",\"팀원 간 원활한 협업을 위한 정기적인 진행 상황 공유 체계를 구축하기로 합의했습니다.\",\"AI 기술을 실무에 적용할 수 있는 실용적인 데이터 분석 솔루션 개발 방향을 확정했습니다.\"]','2026-02-06 00:30:30','2026-02-06 00:30:30','FULL_AUDIO'),(33,2111,NULL,'MIXED','/uploads/meetings/2111/stt/mixed/summary.txt','[{\"id\":842,\"content\":\"사과포도는 회의에서 논의된 퀴즈 생성 시스템의 구체적인 구현 방안과 문제 유형별 가이드라인을 문서화하여 1주일 내 팀원들과 공유\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":843,\"content\":\"온라인 미팅 플랫폼의 최적 설정값과 트러블슈팅 매뉴얼을 작성하여 향후 스터디 진행 시 참고자료로 활용\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":844,\"content\":\"참가자 참여도 측정을 위한 체크리스트와 평가 기준을 수립하여 다음 회의에서 검토\",\"assigneeId\":null,\"status\":\"TODO\"},{\"id\":845,\"content\":\"정기 온라인 스터디 운영을 위한 표준 프로세스와 시간 배분 가이드라인 초안 작성\",\"assigneeId\":null,\"status\":\"TODO\"}]','[\"온라인 미팅\",\"미디어 스트리밍\",\"퀴즈 생성\",\"학습 효과\",\"참가자 참여\",\"WebRTC\",\"실시간 통신\",\"상호작용\",\"사용자 경험\",\"접근성\"]','[\"온라인 미팅 플랫폼의 핵심 기능 설정과 최적화를 통한 안정적인 학습 환경 구축 방안 논의\",\"참가자 참여도 실시간 모니터링과 미디어 스트리밍 품질 관리의 중요성 확인\",\"인터랙티브 퀴즈 생성 시스템을 활용한 능동적 학습 참여 유도 방안 합의\",\"체계적이고 표준화된 온라인 스터디 운영 가이드라인 수립 필요성 도출\",\"일방향 강의에서 양방향 상호작용 학습 모델로의 전환 방향성 설정\"]','2026-02-06 01:26:13','2026-02-06 01:26:13','REALTIME_STT');
