  CONSTRAINT `study_quiz_answer_ibfk_2` FOREIGN KEY (`question_id`) REFERENCES `study_quiz_question` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=50006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
